<?php declare(strict_types=1);use App\Core\Database\Database;use App\Modules\ProjectCosts\Repositories\ProjectCostRepository;/** @var Database $db */$db=$app->make(Database::class);$r=$db->execute("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='project_actual_costs'");if(!($r instanceof mysqli_result)||$r->num_rows!==1)throw new RuntimeException('Project costs table missing.');$permissions=$db->execute("SELECT COUNT(*) total FROM permissions WHERE code LIKE 'project_costs.%'");if((int)($permissions->fetch_assoc()['total']??0)!==5)throw new RuntimeException('Project cost permissions missing.');/** @var ProjectCostRepository $repo */$repo=$app->make(ProjectCostRepository::class);$project=$db->execute("SELECT id FROM projects WHERE status<>'cancelled' LIMIT 1")->fetch_assoc();$code=$db->execute('SELECT c.id FROM cost_codes c JOIN work_sections w ON w.id=c.work_section_id WHERE c.is_active=1 AND w.is_active=1 LIMIT 1')->fetch_assoc();$user=$db->execute('SELECT id FROM users LIMIT 1')->fetch_assoc();if($project&&$code&&$user){$db->connection()->begin_transaction();try{$base=[(int)$project['id'],(int)$code['id'],date('Y-m-d'),'test','1.00',(int)$user['id']];$db->execute("INSERT INTO project_actual_costs(cost_entry_code,project_id,cost_code_id,cost_date,description,amount,source_type,created_by)VALUES(?,?,?,?,?,?,'manual',?)",['TEST-MANUAL-1',...$base]);$db->execute("INSERT INTO project_actual_costs(cost_entry_code,project_id,cost_code_id,cost_date,description,amount,source_type,created_by)VALUES(?,?,?,?,?,?,'manual',?)",['TEST-MANUAL-2',...$base]);$db->execute("INSERT INTO project_actual_costs(cost_entry_code,project_id,cost_code_id,cost_date,description,amount,source_type,source_id,source_line_id,created_by)VALUES(?,?,?,?,?,?,'supplier_invoice',99,1,?)",['TEST-SOURCE-1',...$base]);try{$db->execute("INSERT INTO project_actual_costs(cost_entry_code,project_id,cost_code_id,cost_date,description,amount,source_type,source_id,source_line_id,created_by)VALUES(?,?,?,?,?,?,'supplier_invoice',99,1,?)",['TEST-SOURCE-2',...$base]);throw new RuntimeException('Duplicate source identity accepted.');}catch(mysqli_sql_exception$e){if($e->getCode()!==1062)throw$e;}$summary=$repo->summary((int)$project['id']);if((string)$repo->total((int)$project['id'])===''||!isset($summary['draft_total']))throw new RuntimeException('Cost totals failed.');}finally{$db->connection()->rollback();}}
